SELECT * FROM book
WHERE is_deleted = 0

    AND (title LIKE CONCAT('%', #{keyword}, '%')
         OR author LIKE CONCAT('%', #{keyword}, '%')
         OR publisher LIKE CONCAT('%', #{keyword}, '%')
         OR isbn LIKE CONCAT('%', #{keyword}, '%'))


    AND category_id = #{categoryId}


    AND price >= #{minPrice}


    AND price <= #{maxPrice}


    ORDER BY ${sortField}

        ${sortOrder}



    ORDER BY create_time DESC
